/**
 * The product skill `skills/command-center/SKILL.md` (07 §8 item 3, C-07-06), generated by
 * `pnpm cc:gen` from the help text `cc-axi` itself prints: the top-level help with its hints,
 * the home view's sections with no live data, and each command's usage and summary from the
 * catalogue. `pnpm cc:gen --check` fails when the file is stale.
 */
import { DESCRIPTION, HUMAN_ONLY_VERBS, topLevelHelp } from './help.js';
import { COMMANDS, DEFAULT_LIMIT, GLOBAL_FLAGS, groups, usageOf } from './spec.js';

export const SKILL_NAME = 'command-center';

/** Trigger-shaped, as 07 §8 item 3 gives it. */
export const SKILL_DESCRIPTION =
  'Use when the user asks about their action items, decisions, meetings, scorecards, or Command Center.';

/** The home view's sections (07 §4.3), described instead of shown: the skill holds no live data. */
const HOME_SECTIONS: readonly (readonly [string, string])[] = [
  ['bin, description', 'where `cc-axi` is, and what Command Center is'],
  ['workspace, now', 'the workspace and its local time'],
  ['today', "today's meetings: ref, time, meeting"],
  [
    'attention',
    'counts of overdue, at-risk and awaiting-review items, pending confirmations and browser sessions that need the user',
  ],
  ['items, count', 'the most urgent items (ref, title, due, state) out of all due within 7 days'],
  ['help', 'the next commands to run'],
];

export function renderSkill(): string {
  const help = topLevelHelp();
  const hints = (help['help'] as string[] | undefined) ?? [];
  const lines = [
    '---',
    `name: ${SKILL_NAME}`,
    `description: ${SKILL_DESCRIPTION}`,
    '---',
    '',
    '# Command Center',
    '',
    '<!-- Generated by `pnpm cc:gen` from apps/cli/src (07 §8). Do not edit by hand. -->',
    '',
    `${DESCRIPTION}. You work with it through \`cc-axi\`, its command line for agents. Output is TOON on stdout, errors included; add \`--format json\` only for scripts.`,
    '',
    '## Start here',
    '',
    'Run `cc-axi` with no arguments. The home view shows what is live now:',
    '',
    ...HOME_SECTIONS.map(([keys, meaning]) => `- \`${keys}\`: ${meaning}`),
    '',
    'Then:',
    '',
    ...hints.map((hint) => `- ${hint}.`),
    '',
    `Item refs look like \`A-0142\`, decisions \`D-0008\`, issues \`I-0012\`, measures \`K-0003\` and meetings \`M-0031\`. Lists show ${DEFAULT_LIMIT} rows unless \`--limit\` says otherwise, with a \`count:\` line of shown and total, and \`help:\` lines that name the next command.`,
    '',
    '## Commands',
  ];
  for (const group of groups()) {
    const commands = COMMANDS.filter(
      (command) => command.path === group || command.path.startsWith(`${group} `),
    );
    lines.push('', `### ${group}`, '');
    for (const command of commands) {
      lines.push(`- \`${usageOf(command)}\`: ${command.summary}.`);
    }
  }
  lines.push(
    '',
    `Flags come after the command. Every command also takes ${GLOBAL_FLAGS.map((flag) => `\`${flag.name} ${flag.value ?? ''}\` (${flag.description.toLowerCase()})`).join(', ')}, and \`--help\` for its flags, defaults and examples.`,
    '',
    '## Rules',
    '',
    `- The user does these in the app, never an agent: ${[...HUMAN_ONLY_VERBS].join(', ')}. A command that needs the user returns \`pending_confirmation\` or \`E_HUMAN_REQUIRED\` with a deep link; tell the user, and do not look for another way.`,
    '- Items you create are drafts until the user accepts them. A claim needs evidence (a URL, `file:<path>` or `record:<binding>/<type>/<externalId>`); the user verifies it.',
    '- Errors print `error:`, `code:` and `help:` on stdout. Exit 1 is an error, exit 2 a usage error (`E_USAGE`, `E_UNKNOWN_FLAG`): read the help line and fix the command. A repeated mutation prints `status: no-op` and exits 0.',
    '- `E_APP_NOT_RUNNING` means the Command Center app is closed: ask the user to open it.',
    '- `--principal <name>` (or `$CC_PRINCIPAL`) names the agent principal you act as; the user grants its scopes and workstreams in the app.',
    '',
    '## Ambient context',
    '',
    "With the user's go-ahead, `cc-axi setup hooks` installs a SessionStart hook for Claude Code, Codex and OpenCode (`--scope project` for one repository). Each new session then starts with `cc-axi hook session-start`: today's meetings, the attention counts and the top items of the workstream mapped to the current directory. `cc-axi setup status` shows what is installed.",
    '',
  );
  return lines.join('\n');
}
